import ApiError from './ApiError.js';
import AuthSession from './AuthSession.js';
import LoginModalEvents from './LoginModalEvents.js';

const REFRESH_PATH = '/auth/refresh.json';
const FALLBACK_ERROR_MESSAGE = 'Request failed';

/**
 * Parse a response's JSON body, without attempting to parse an empty body (e.g. a
 * `204 No Content` response, as returned by `DELETE /auth/logoff.json`) — `response.json()`
 * throws a `SyntaxError` on an empty string, since it is not valid JSON. A non-JSON body
 * (e.g. an HTML error page generated by the proxy) is also treated as `{}`, so error handling
 * can fall back to a generic message instead of crashing on the parse.
 *
 * @param {Response} response - The raw `fetch` response.
 * @returns {Promise<object>} The parsed JSON body, or `{}` when the response has no JSON body.
 */
async function parseBody(response) {
  if (response.status === 204) {
    return {};
  }

  const text = await response.text();

  return text === '' ? {} : parseJson(text);
}

/**
 * Parse a JSON string, tolerating invalid JSON.
 *
 * @param {string} text - The raw response body.
 * @returns {object} The parsed value, or `{}` when `text` is not valid JSON.
 */
function parseJson(text) {
  try {
    return JSON.parse(text);
  } catch {
    return {};
  }
}

/**
 * Parse a response's `Retry-After` header as integer seconds.
 *
 * @description Only the delta-seconds form is supported (the backend never sends an HTTP
 * date). Tolerates a response without `headers` (e.g. a minimal fake in specs).
 * @param {Response} response - The raw `fetch` response.
 * @returns {number|undefined} The non-negative number of seconds to wait, or `undefined` when
 *   the header is absent or not a non-negative integer.
 */
function parseRetryAfter(response) {
  const value = response.headers?.get('Retry-After');

  if (typeof value !== 'string' || !/^\d+$/.test(value.trim())) {
    return undefined;
  }

  return Number.parseInt(value.trim(), 10);
}

/**
 * Build the {@link ApiError} for a failed response.
 *
 * @description Reads the backend's standard error body
 * (`{ error: { code, message, details? }, statusCode, timestamp }`). Falls back to the
 * response's `statusText`, then to a generic message, when the body carries no
 * `error.message` (e.g. a proxy-generated or empty error response), so the resulting error's
 * `message` is never `undefined`. Carries the `Retry-After` header (integer seconds), when
 * present and valid, as the error's `retryAfter`.
 * @param {Response} response - The raw `fetch` response.
 * @param {object} data - The parsed response body.
 * @returns {ApiError} The error to throw.
 */
function buildApiError(response, data) {
  const error = data?.error ?? {};
  const message = error.message || response.statusText || FALLBACK_ERROR_MESSAGE;

  return new ApiError(
    response.status, message, error.code, error.details, parseRetryAfter(response),
  );
}

/**
 * Perform a raw JSON request, without any `401`-recovery behavior.
 *
 * @param {string} method - HTTP method.
 * @param {string} path - Request path.
 * @param {object} body - Fields to serialize as the JSON request body.
 * @returns {Promise<{response: Response, data: object}>} The raw response and its parsed
 *   JSON body.
 */
async function request(method, path, body) {
  const response = await fetch(path, {
    method,
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify(body),
  });

  const data = await parseBody(response);

  return { response, data };
}

/**
 * End the client-side session: open the login modal in Password mode via the shared
 * {@link LoginModalEvents} bus — a pure client-side state transition, with no API call of its
 * own. The backend already cleared the session cookies on the failed refresh, so there is no
 * client-side storage to clear. SSR/spec-safe — a no-op when `window` is not defined, the same
 * way the shared `redirectHome` helper guards it.
 *
 * @returns {undefined} Always `undefined`, so callers can `return` it directly.
 */
function sessionExpired() {
  if (typeof window !== 'undefined') {
    LoginModalEvents.open('password');
  }

  return undefined;
}

/**
 * Submit a JSON request, always sending same-origin credentials so the session cookie set
 * by the backend (via `Set-Cookie`) is stored/sent automatically. On a `401`, delegates to
 * {@link handleUnauthorized} unless this is already a retried request, in which case the
 * session is treated as expired directly.
 *
 * @param {string} method - HTTP method.
 * @param {string} path - Request path.
 * @param {object} body - Fields to serialize as the JSON request body.
 * @param {boolean} [isRetry] - Whether this call is already a post-refresh retry.
 * @returns {Promise<object>} The parsed JSON response body, on success; `undefined` when the
 *   session turned out to be expired.
 */
async function sendJson(method, path, body, isRetry = false) {
  const { response, data } = await request(method, path, body);

  if (response.ok) {
    return data;
  }

  if (response.status === 401) {
    return isRetry
      ? sessionExpired()
      : handleUnauthorized(method, path, body);
  }

  throw buildApiError(response, data);
}

/**
 * Recover from a `401` on the original request: refresh the access token (the httpOnly
 * `refresh_token` cookie rides along automatically) and retry the original request once. Falls
 * back to session-expired handling when the `logged_in` hint cookie is absent, or when the
 * refresh call itself fails.
 *
 * @param {string} method - Original request's HTTP method.
 * @param {string} path - Original request's path.
 * @param {object} body - Original request's JSON body.
 * @returns {Promise<object>} The retried request's parsed JSON body, on success; `undefined`
 *   when the session turned out to be expired.
 */
async function handleUnauthorized(method, path, body) {
  if (!AuthSession.isLoggedIn()) {
    return sessionExpired();
  }

  const refreshResponse = await request('POST', REFRESH_PATH, {});

  if (!refreshResponse.response.ok) {
    return sessionExpired();
  }

  return sendJson(method, path, body, true);
}

/**
 * Generic JSON HTTP client used by resource-specific clients. Transparently recovers from an
 * expired access token: on a `401`, it refreshes the session once (via the httpOnly
 * `refresh_token` cookie) and retries the original request; if the `logged_in` hint cookie is
 * absent, or the refresh itself fails, the session is treated as expired.
 */
const ApiClient = {
  /**
   * Submit a POST request with a JSON body. Always sends same-origin credentials so the
   * session cookie set by the backend (via `Set-Cookie`) is stored/sent automatically.
   *
   * @param {string} path - Request path.
   * @param {object} body - Fields to serialize as the JSON request body.
   * @returns {Promise<object>} The parsed JSON response body, on success; `undefined` when the
   *   session turned out to be expired.
   */
  async postJson(path, body) {
    return sendJson('POST', path, body);
  },

  /**
   * Submit a DELETE request with a JSON body. Same headers/credentials/error-handling shape
   * as {@link ApiClient.postJson}.
   *
   * @param {string} path - Request path.
   * @param {object} body - Fields to serialize as the JSON request body.
   * @returns {Promise<object>} The parsed JSON response body, on success; `undefined` when the
   *   session turned out to be expired.
   */
  async deleteJson(path, body) {
    return sendJson('DELETE', path, body);
  },

  /**
   * Submit a PATCH request with a JSON body. Same headers/credentials/error-handling shape
   * as {@link ApiClient.postJson}.
   *
   * @param {string} path - Request path.
   * @param {object} body - Fields to serialize as the JSON request body.
   * @returns {Promise<object>} The parsed JSON response body, on success; `undefined` when the
   *   session turned out to be expired.
   */
  async patchJson(path, body) {
    return sendJson('PATCH', path, body);
  },

  /**
   * Submit a POST request with a JSON body through the raw path: no `401`-refresh-and-retry
   * loop and no session-expired handling.
   *
   * @param {string} path - Request path.
   * @param {object} body - Fields to serialize as the JSON request body.
   * @returns {Promise<object>} The parsed JSON response body, on success.
   * @throws {ApiError} When the response is not successful.
   */
  async postJsonOnce(path, body) {
    const { response, data } = await request('POST', path, body);

    if (!response.ok) {
      throw buildApiError(response, data);
    }

    return data;
  },
};

export default ApiClient;
